extends Node

@export var previous_definition: GameDefinition


func _ready() -> void:
    if previous_definition == null:
        push_error("Assign the existing game definition before starting.")
        return

    var game: Game = GameConfig.from_definition(previous_definition).boot(self)
    var started: GameResult = await game.play()
    if not started.ok:
        push_error(started.message)
        return

    print("The saved starting world is ready.")

extends CheckButton

@export var match_owner: Node


func _ready() -> void:
    toggled.connect(_select_default)


func _select_default(use_match: bool) -> void:
    var selected: Game
    if use_match:
        selected = Game.for_node(match_owner)
        if selected == null:
            set_pressed_no_signal(false)
            push_warning("Start the match before selecting it.")
            return

    var status: int = Game.set_default(selected)
    if status != OK:
        set_pressed_no_signal(not use_match)
        push_error("Could not update the default game.")
        return

    var current: Game = Game.current()
    if current == null:
        print("No default game selected.")
    else:
        print("Debug game phase: %d" % current.get_phase())
